import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03105Controller {
  @Get('/attachments/:attachmentId/download')
  async downloadAttachment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    checks.queryOf(req.query);
    const attachmentId = req.params['attachmentId'];
    if (!/^[0-9]+$/.test(attachmentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부파일 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT attachment_id AS "attachmentId",
                file_name AS "fileName",
                ecm_file_key AS "ecmFileKey"
           FROM attachment
          WHERE attachment_id = CAST(:attachmentId AS bigint)`,
        { attachmentId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTACHMENT_NOT_FOUND', '첨부파일이 존재하지 않습니다.');
      }
      const row = rows[0];
      if (!row.ecmFileKey) {
        throw new ApiError(502, 'ECM_READ_FAILED', 'ECM 저장소에서 파일을 읽지 못했습니다.');
      }
      // 가정: ECM 저장소에서 ecm_file_key 파일을 읽는 연계 모듈이 없어 내용은 비워 둔다.
      return {
        fileName: row.fileName,
        fileContent: null,
      };
    });
  }
}

