import { useState } from 'react';
import {
  call,
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Form,
  NumberInput,
  Pairs,
  RefName,
  TextInput,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03105Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [file, setFile] = useState('');
  const [ownerType, setOwnerType] = useState('');
  const [ownerId, setOwnerId] = useState<number | string>('');
  const [targetId, setTargetId] = useState<number | string>('');
  const [preview, setPreview] = useState<Row | null>(null);
  const [download, setDownload] = useState<Row | null>(null);

  async function create() {
    if (!file) {
      throw new Error('업로드 파일을 입력하세요.');
    }
    const body: Row = { file };
    if (ownerType) body.ownerType = ownerType;
    if (ownerId !== '') body.ownerId = ownerId;
    const res = await call('POST', '/attachments', role, body);
    setResults([res, ...results]);
    setCreating(false);
    setFile('');
    setOwnerType('');
    setOwnerId('');
    notify('첨부파일을 등록했습니다.');
  }

  async function openPreview(id: unknown) {
    if (id === '' || id === undefined) {
      throw new Error('첨부파일 ID를 입력하세요.');
    }
    const res = await call('GET', `/attachments/${id}/preview`, role);
    setPreview(res);
  }

  async function openDownload(id: unknown) {
    if (id === '' || id === undefined) {
      throw new Error('첨부파일 ID를 입력하세요.');
    }
    const res = await call('GET', `/attachments/${id}/download`, role);
    setDownload(res);
    notify('다운로드 파일을 받았습니다.');
  }

  async function safe(action: () => Promise<void>) {
    try {
      await action();
    } catch (e) {
      notify(e instanceof Error ? e.message : '처리하지 못했습니다.');
    }
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[['이번 화면에서 등록', results.length]]} />
      </section>
      <section className="box span-8">
        <h2>등록한 첨부파일</h2>
        <Band total={results.length}>
          <button onClick={() => setCreating(true)}>첨부파일 등록</button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 등록한 첨부파일이 없습니다."
          columns={[
            {
              key: 'attachmentId',
              label: '첨부파일 ID',
              render: (r) => <RefName table="attachment" role={role} value={r.attachmentId} />,
            },
            { key: 'fileName', label: '파일명' },
            {
              key: 'action',
              label: '열람',
              render: (r) => (
                <span>
                  <button onClick={() => safe(() => openPreview(r.attachmentId))}>미리보기</button>
                  <button onClick={() => safe(() => openDownload(r.attachmentId))}>다운로드</button>
                </span>
              ),
            },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>첨부파일 열람</h2>
        <Field label="첨부파일 ID">
          <NumberInput value={targetId} onChange={setTargetId} />
        </Field>
        <button onClick={() => safe(() => openPreview(targetId))}>미리보기</button>
        <button onClick={() => safe(() => openDownload(targetId))}>다운로드</button>
      </section>
      {creating && (
        <Drawer title="첨부파일 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="등록">
            <Field label="업로드 파일" required wide>
              <TextInput value={file} onChange={setFile} multiline />
            </Field>
            <Field label="소유 대상 유형">
              <TextInput value={ownerType} onChange={setOwnerType} />
            </Field>
            <Field label="소유 대상 식별자">
              <NumberInput value={ownerId} onChange={setOwnerId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {preview && (
        <Drawer title="첨부파일 미리보기" onClose={() => setPreview(null)}>
          <Pairs
            items={[
              ['파일명', String(preview.fileName ?? '')],
              ['확장자', <Badge value={preview.fileExt} />],
              ['변환된 미리보기 내용', String(preview.previewContent ?? '')],
            ]}
          />
        </Drawer>
      )}
      {download && (
        <Drawer title="첨부파일 다운로드" onClose={() => setDownload(null)}>
          <Pairs
            items={[
              ['파일명', String(download.fileName ?? '')],
              ['다운로드 파일', String(download.fileContent ?? '')],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
